insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g4_ss_v1'
from (values
('113.15.c.1.A',3,'Some scientists think the first people in Texas came from Asia by crossing a land bridge. What does that idea explain?','["a possible origin of American Indian groups", "why Texas has bluebonnets", "why rivers flow to the Gulf", "how oil formed"]'::jsonb,0,'It is a theory about where early peoples came from.','original'),
('113.15.c.1.B',3,'Which Texas group lived on the coast and hunted and fished along the Gulf?','["Jumano", "Karankawa", "Caddo", "Comanche"]'::jsonb,1,'The Karankawa lived along the Gulf Coast.','original'),
('113.15.c.1.B',3,'The Caddo of East Texas were known for what way of life?','["mining silver", "living on boats", "farming and living in grass houses in villages", "following buffalo herds in tipis only"]'::jsonb,2,'The Caddo farmed corn, beans and squash.','original'),
('113.15.c.1.B',3,'Which group moved across the plains following buffalo and lived in tipis?','["Alabama-Coushatta", "Caddo", "Pueblo", "Lipan Apache"]'::jsonb,3,'The Lipan Apache hunted buffalo on the plains.','original'),
('113.15.c.1.C',3,'Which of these is a cultural region where American Indians lived in Texas?','["Plains", "Pacific Northwest", "Great Lakes", "Arctic"]'::jsonb,0,'Plains, Gulf, Puebloan and Southeastern are Texas regions.','original'),
('113.15.c.1.C',3,'Which cultural region is known for adobe homes and farming near the Rio Grande?','["Gulf", "Puebloan", "Southeastern", "Plains"]'::jsonb,1,'Puebloan peoples built with adobe.','original'),
('113.15.c.1.D',3,'The Ysleta Del Sur Pueblo is a tribe still found near which Texas city?','["Dallas", "Houston", "El Paso", "Amarillo"]'::jsonb,2,'The Ysleta Del Sur Pueblo is in El Paso.','original'),
('113.15.c.1.D',3,'The Alabama-Coushatta tribe lives on a reservation in which part of Texas?','["West Texas desert", "the Rio Grande Valley", "the Panhandle", "East Texas piney woods"]'::jsonb,3,'Their reservation is near Livingston.','original'),
('113.15.c.2.A',3,'Which was a major reason European countries explored Texas?','["to find wealth and claim land", "to start airlines", "to study electricity", "to build amusement parks"]'::jsonb,0,'Explorers looked for gold and new territory.','original'),
('113.15.c.2.A',3,'Spain and France both wanted Texas land. This is an example of...','["a cattle drive", "competition between countries", "a school lesson", "a peace treaty"]'::jsonb,1,'Countries competed for territory.','original'),
('113.15.c.2.B',3,'Which explorer was shipwrecked and walked across Texas, writing about what he saw?','["Stephen F. Austin", "La Salle", "Cabeza de Vaca", "Coronado"]'::jsonb,2,'Cabeza de Vaca crossed Texas in the 1500s.','original'),
('113.15.c.2.B',3,'Which explorer searched for the legendary Cities of Gold?','["Sam Houston", "Anson Jones", "Lizzie Johnson", "Francisco Coronado"]'::jsonb,3,'Coronado searched for riches that did not exist.','original'),
('113.15.c.2.B',3,'La Salle''s French colony in Texas is remembered because it...','["gave France a claim that made Spain settle Texas", "started the cattle industry", "became the capital", "built the Alamo"]'::jsonb,0,'His landing made Spain act to protect its claim.','original'),
('113.15.c.2.C',3,'Why did Spain build missions in Texas?','["to run railroads", "to spread the Catholic faith and hold the land", "to sell cars", "to mine coal"]'::jsonb,1,'Missions taught religion and claimed land.','original'),
('113.15.c.2.C',3,'San Antonio de Valero is better known by what name?','["San Jacinto", "Goliad", "the Alamo", "Fort Worth"]'::jsonb,2,'The mission became the Alamo.','original'),
('113.15.c.2.D',3,'When Mexico fought for independence from Spain, Texas became...','["part of France", "part of Canada", "a U.S. state at once", "part of the new Mexican nation"]'::jsonb,3,'Mexico won independence in 1821.','original'),
('113.15.c.2.E',3,'What was an empresario?','["a person who brought settlers to Texas under a contract", "a mission priest", "a cattle driver", "a railroad worker"]'::jsonb,0,'Empresarios recruited colonists for land grants.','original'),
('113.15.c.2.E',3,'Stephen F. Austin is called the "Father of Texas" because he...','["invented the cotton gin", "led the first Anglo settlement of Texas colonists", "drew the first state flag", "found oil at Spindletop"]'::jsonb,1,'Austin settled the Old Three Hundred.','original'),
('113.15.c.2.E',3,'Martin De Leon founded which colony?','["Amarillo", "El Paso", "Victoria", "Houston"]'::jsonb,2,'De Leon founded a Mexican-led colony at Victoria.','original'),
('113.15.c.3.A',3,'Which Texas Revolution battle took place at a mission in San Antonio in 1836?','["the Red River War", "the Battle of Gettysburg", "the Battle of Bunker Hill", "the Battle of the Alamo"]'::jsonb,3,'Texans defended the Alamo for thirteen days.','original'),
('113.15.c.3.A',3,'What was the Runaway Scrape?','["when Texas families fled east from Santa Anna''s army", "a railroad race", "a cattle stampede", "a rodeo event"]'::jsonb,0,'Settlers escaped the advancing army.','original'),
('113.15.c.3.A',3,'Which battle ended the Texas Revolution?','["Goliad", "San Jacinto", "the Alamo", "Gonzales"]'::jsonb,1,'Texans won at San Jacinto in 1836.','original'),
('113.15.c.3.A',3,'The Texas Declaration of Independence said that Texas was...','["part of France", "a U.S. territory", "free from Mexico", "part of Spain"]'::jsonb,2,'It announced independence from Mexico.','original'),
('113.15.c.3.B',3,'Who commanded the Texas army at the Battle of San Jacinto?','["William B. Travis", "Mirabeau Lamar", "David Crockett", "Sam Houston"]'::jsonb,3,'Houston led the victory.','original'),
('113.15.c.3.B',3,'Juan Seguin is remembered for...','["serving as a Tejano captain in the Texas Revolution", "writing a constitution alone", "building the Alamo", "inventing barbed wire"]'::jsonb,0,'Seguin fought and led Tejano soldiers.','original'),
('113.15.c.3.B',3,'Who was a lawyer who wrote a famous letter asking for help from the Alamo?','["Jim Bowie", "William B. Travis", "Santa Anna", "David Crockett"]'::jsonb,1,'Travis wrote his "Victory or Death" letter.','original'),
('113.15.c.3.C',3,'Who was the first president of the Republic of Texas elected in 1836?','["Lizzie Johnson", "Anson Jones", "Sam Houston", "Stephen F. Austin"]'::jsonb,2,'Houston served as the first president.','original'),
('113.15.c.3.C',3,'Who was the last president of the Republic of Texas?','["Jose Navarro", "Mirabeau Lamar", "Sam Houston", "Anson Jones"]'::jsonb,3,'Jones oversaw annexation.','original'),
('113.15.c.3.C',3,'Jose Antonio Navarro is remembered because he...','["signed the Texas Declaration of Independence", "led the Union army", "invented the telephone", "ran a railroad"]'::jsonb,0,'Navarro was a Tejano signer.','original'),
('113.15.c.3.D',3,'A big problem for the Republic of Texas was...','["too many railroads", "owing a lot of money", "too much snow", "having too many cars"]'::jsonb,1,'The Republic struggled with debt.','original'),
('113.15.c.3.D',3,'The Republic of Texas wrote its own...','["road atlas", "cookbook", "constitution", "flag of a different country"]'::jsonb,2,'It created a constitution in 1836.','original'),
('113.15.c.3.E',3,'In 1845 Texas became...','["a province of Canada", "a colony of Spain", "a territory of France", "a state of the United States"]'::jsonb,3,'Annexation made Texas the 28th state.','original'),
('113.15.c.3.E',3,'The war between the U.S. and Mexico (1846-1848) began partly over...','["the Texas border", "railroad tickets", "the telegraph", "cotton prices only"]'::jsonb,0,'Disputed borders led to war.','original'),
('113.15.c.4.A',3,'Which war divided the nation, and Texas joined the Confederacy?','["World War I", "the Civil War", "the Revolutionary War", "the Mexican War of Independence"]'::jsonb,1,'Texas seceded in 1861.','original'),
('113.15.c.4.A',3,'Reconstruction was the time...','["of the Great Depression", "of the Dust Bowl", "after the Civil War when the South was rebuilt", "before the Revolution"]'::jsonb,2,'It followed the war.','original'),
('113.15.c.4.B',3,'Cattle drives in Texas took herds along trails to...','["New York", "the Pacific Ocean", "Mexico City", "railroads in Kansas"]'::jsonb,3,'Cowboys drove cattle north to rail towns.','original'),
('113.15.c.4.B',3,'Charles Goodnight is remembered for...','["blazing a famous cattle trail", "writing the constitution", "building the Alamo", "discovering oil"]'::jsonb,0,'The Goodnight-Loving Trail helped cattle drives.','original'),
('113.15.c.4.B',3,'Which ranch founder started the King Ranch?','["Audie Murphy", "Richard King", "Mirabeau Lamar", "Sam Houston"]'::jsonb,1,'King built a huge South Texas ranch.','original'),
('113.15.c.4.B',3,'Lizzie Johnson was important to the cattle industry as...','["an astronaut", "a president", "a rancher and trail driver", "a mission priest"]'::jsonb,2,'She was a businesswoman who drove her own herds.','original'),
('113.15.c.4.C',3,'How did railroads change life in Texas?','["they closed towns", "they stopped trade", "they ended farming", "they helped towns grow and moved goods quickly"]'::jsonb,3,'Railroads connected markets.','original'),
('113.15.c.4.D',3,'What happened to the buffalo in the 1800s that hurt Plains Indians?','["they were nearly all hunted out", "they became pets", "they learned to fly", "they moved to Canada by choice"]'::jsonb,0,'Loss of buffalo harmed their way of life.','original'),
('113.15.c.4.D',3,'The Red River War ended with...','["the end of the railroad", "American Indians being moved to reservations", "a new state capital", "a gold rush"]'::jsonb,1,'The war ended Plains Indian resistance.','original'),
('113.15.c.5.A',3,'The Dust Bowl was caused by drought and...','["too many lakes", "too much snow", "poor farming practices that left soil to blow away", "a volcano"]'::jsonb,2,'Dry soil blew away in great storms.','original'),
('113.15.c.5.A',3,'The Great Depression was a time when...','["Texas became a state", "trains stopped running forever", "everyone got rich", "many people lost jobs and money"]'::jsonb,3,'Banks failed and unemployment rose.','original'),
('113.15.c.5.A',3,'Audie Murphy, a Texan, is remembered for...','["being a World War II hero", "running a mission", "inventing the airplane", "founding Houston"]'::jsonb,0,'He was the most decorated U.S. soldier of the war.','original'),
('113.15.c.5.B',3,'Spindletop, near Beaumont, was important because...','["it was a mission", "it was a huge oil gusher that began the Texas oil boom", "it was a cattle trail", "it was a fort"]'::jsonb,1,'The 1901 gusher changed the state economy.','original'),
('113.15.c.5.B',3,'Oil and gas helped Texas cities grow by...','["stopping trade", "ending railroads", "creating jobs and drawing workers", "closing all stores"]'::jsonb,2,'Industry drew people to cities.','original'),
('113.15.c.6.A',3,'Which Texas region includes the Panhandle and is flat and dry?','["Coastal Plains", "North Central Plains", "Mountains and Basins", "Great Plains"]'::jsonb,3,'The Great Plains are high and flat.','original'),
('113.15.c.6.A',3,'Which region of Texas has the Guadalupe Mountains?','["Mountains and Basins", "Great Plains", "North Central Plains", "Coastal Plains"]'::jsonb,0,'It lies in far West Texas.','original'),
('113.15.c.6.A',3,'Which Texas region runs along the Gulf of Mexico and has hot, humid weather?','["Mountains and Basins", "Coastal Plains", "North Central Plains", "Great Plains"]'::jsonb,1,'The Coastal Plains border the Gulf.','original'),
('113.15.c.6.B',3,'Compared with the Coastal Plains, the Mountains and Basins region is...','["colder and wetter", "lower and wetter", "higher and drier", "flatter and wetter"]'::jsonb,2,'West Texas has higher, drier land.','original'),
('113.15.c.7.A',3,'Why did many early settlers choose land near rivers?','["rivers had no fish", "they wanted deserts", "rivers were noisy", "they needed water and good soil"]'::jsonb,3,'Water supports farming and travel.','original'),
('113.15.c.7.B',3,'Many large Texas cities grew along...','["rivers, coasts, and railroads", "only the Panhandle border", "only mountain tops", "only deserts"]'::jsonb,0,'Resources and routes shaped city locations.','original'),
('113.15.c.8.A',3,'Which is a way Texans modify the environment?','["changing the seasons", "building dams and reservoirs", "growing taller trees by wishing", "moving the Gulf"]'::jsonb,1,'Dams store water for people.','original'),
('113.15.c.8.B',3,'Farmers drain wetlands in order to...','["stop rain", "remove oil", "make more land for crops", "cool the air"]'::jsonb,2,'Draining creates farmland.','original'),
('113.15.c.8.C',3,'A negative consequence of cutting too many trees can be...','["colder summers", "more tall buildings", "more rain every day", "soil erosion"]'::jsonb,3,'Roots hold soil in place.','original'),
('113.15.c.9.A',3,'How did Plains Indians meet their needs and wants?','["by hunting buffalo and trading", "by flying planes", "by running factories", "by selling cars"]'::jsonb,0,'They used buffalo for food, clothing and shelter.','original'),
('113.15.c.9.B',3,'How did early Texas settlers meet their needs?','["by using computers", "by farming and ranching", "by driving trucks", "by building skyscrapers"]'::jsonb,1,'They grew crops and raised livestock.','original'),
('113.15.c.10.A',3,'In a free enterprise system, prices are affected by...','["a coin flip", "the weather alone", "supply and demand", "a king''s order"]'::jsonb,2,'Buyers and sellers shape prices.','original'),
('113.15.c.10.B',3,'One benefit of free enterprise is...','["nobody may own a business", "there are no choices", "the government sets every job", "people can choose what to buy and what business to start"]'::jsonb,3,'Choice and opportunity are key.','original'),
('113.15.c.10.C',3,'Cash crops grown by early colonists, like cotton, helped...','["the free enterprise system grow in Texas", "end ranching", "stop trade", "close ports"]'::jsonb,0,'Cotton was sold for money.','original'),
('113.15.c.11.A',3,'Which type of work is common in the coastal region of Texas?','["skiing", "fishing and shipping", "wheat farming only", "mountain mining only"]'::jsonb,1,'Ports and fishing fit the Gulf.','original'),
('113.15.c.11.B',3,'Why is oil drilled where it is found underground?','["oil only exists in cities", "oil likes mountains", "natural resources decide where the work happens", "oil moves by itself"]'::jsonb,2,'Resources decide location.','original'),
('113.15.c.11.C',3,'Immigrants who came to Texas helped its economy by...','["stopping all farming", "closing railroads", "leaving the state empty", "bringing new skills, labor, and businesses"]'::jsonb,3,'Immigration grew the workforce.','original'),
('113.15.c.11.D',3,'How did the telegraph and telephone change business in Texas?','["people could share news and orders quickly", "trade ended", "people stopped working", "farms disappeared"]'::jsonb,0,'Faster communication helped business.','original'),
('113.15.c.12.A',3,'Caddo leaders ruled their villages by...','["a king from Spain", "a chief and a council", "an elected president", "a governor"]'::jsonb,1,'Caddo government was led by chiefs.','original'),
('113.15.c.12.B',3,'Spanish colonial government in Texas was run by...','["Texas voters", "a Mexican general", "a king far away in Spain", "American Indian councils"]'::jsonb,2,'The Spanish king controlled colonies.','original'),
('113.15.c.13.A',3,'The Texas Constitution is important because it...','["marks highways", "lists recipes", "names the state bird", "sets up how the state government works"]'::jsonb,3,'It is the state''s basic law.','original'),
('113.15.c.13.B',3,'Which branch of Texas government makes laws?','["the legislature", "the governor", "the mayor", "the court"]'::jsonb,0,'The legislature writes laws.','original'),
('113.15.c.13.B',3,'Which branch of Texas government carries out laws, led by the governor?','["the military", "the executive branch", "the judicial branch", "the legislative branch"]'::jsonb,1,'The governor leads the executive branch.','original'),
('113.15.c.13.B',3,'Which branch of Texas government decides whether laws are broken or fair?','["the school board", "the legislative branch", "the judicial branch", "the executive branch"]'::jsonb,2,'Courts interpret the law.','original'),
('113.15.c.13.C',3,'The Bill of Rights is...','["a map", "a Texas cookbook", "a river", "the first ten amendments to the U.S. Constitution"]'::jsonb,3,'It protects personal freedoms.','original'),
('113.15.c.14.A',3,'How many flags have flown over Texas?','["six", "ten", "two", "three"]'::jsonb,0,'Spain, France, Mexico, Republic of Texas, Confederacy and U.S.','original'),
('113.15.c.14.A',3,'The San Jacinto Monument honors...','["the railroad", "the Texas victory in the Texas Revolution", "a gold rush", "oil workers"]'::jsonb,1,'It marks the 1836 battle site.','original'),
('113.15.c.14.C',3,'The Pledge to the Texas Flag expresses loyalty to...','["a king", "Mexico", "the state of Texas", "a city"]'::jsonb,2,'Texans pledge to their state.','original'),
('113.15.c.14.D',3,'Texas Independence Day is celebrated on...','["June 1", "July 4", "December 25", "March 2"]'::jsonb,3,'It marks the 1836 declaration.','original'),
('113.15.c.14.D',3,'Juneteenth marks the day...','["enslaved people in Texas learned they were free", "the Alamo fell", "oil was found", "Texas became a state"]'::jsonb,0,'It celebrates June 19, 1865.','original'),
('113.15.c.15.A',3,'Adina De Zavala is remembered for working to...','["build railroads", "save the Alamo and Texas history sites", "drive cattle", "find oil"]'::jsonb,1,'She preserved historic places.','original'),
('113.15.c.15.A',3,'Clara Driscoll helped by...','["signing the Declaration", "inventing a plow", "buying land to save the Alamo", "leading an army"]'::jsonb,2,'She gave money to protect it.','original'),
('113.15.c.15.B',3,'One way a citizen can take part in local government is to...','["break laws", "stay silent always", "ignore public issues", "attend a city council meeting"]'::jsonb,3,'Citizens can speak at meetings.','original'),
('113.15.c.15.C',3,'A citizen has a duty in elections to...','["be informed and vote", "avoid news", "stay away", "spread rumors"]'::jsonb,0,'Informed voting is a responsibility.','original'),
('113.15.c.15.D',3,'Barbara Jordan was a Texan who...','["fought at San Jacinto", "served in Congress and gave powerful speeches", "invented the cotton gin", "ran the King Ranch"]'::jsonb,1,'Jordan was a leader in the U.S. House.','original'),
('113.15.c.15.E',3,'How can you contact your elected leaders?','["wait for them to guess", "shout in a field", "write a letter or send an email", "do nothing"]'::jsonb,2,'Leaders accept messages from citizens.','original'),
('113.15.c.15.F',3,'The class votes on a field trip. Voting is a way to...','["hide an answer", "end a class", "stop learning", "make a group decision"]'::jsonb,3,'Votes decide group choices.','original'),
('113.15.c.16.A',3,'Who is the leader of the Texas state government?','["the governor", "the President", "the principal", "the mayor"]'::jsonb,0,'The governor leads Texas.','original'),
('113.15.c.16.A',3,'Each state has two people in the U.S. Senate called...','["judges", "senators", "governors", "mayors"]'::jsonb,1,'Two senators represent each state.','original'),
('113.15.c.16.B',3,'Which quality is important in a good leader?','["selfishness", "rudeness", "honesty", "laziness"]'::jsonb,2,'Honest leaders earn trust.','original'),
('113.15.c.17.A',3,'Cinco de Mayo is a celebration of...','["the Alamo", "the Boston Tea Party", "the Fourth of July", "Mexican heritage and the Battle of Puebla"]'::jsonb,3,'It honors a Mexican victory in 1862.','original'),
('113.15.c.17.A',3,'Oktoberfest in Texas towns celebrates which heritage?','["German", "Chinese", "Greek", "Egyptian"]'::jsonb,0,'German settlers brought the tradition.','original'),
('113.15.c.17.B',3,'Lydia Mendoza is called the "Lark of the Border" for her work in...','["painting", "Tejano music", "farming", "politics"]'::jsonb,1,'She was a famous Mexican American singer.','original'),
('113.15.c.18.A',3,'Gail Borden is known for...','["building the Alamo", "leading the Texas army", "inventing condensed milk", "inventing barbed wire"]'::jsonb,2,'Borden was a Texas inventor.','original'),
('113.15.c.18.A',3,'Joseph Glidden invented...','["the airplane", "the telephone", "the railroad", "barbed wire"]'::jsonb,3,'Barbed wire helped fence ranches.','original'),
('113.15.c.18.A',3,'Michael DeBakey was a Houston doctor who...','["helped develop heart surgery tools", "led cattle drives", "won a war", "built railroads"]'::jsonb,0,'He advanced heart surgery.','original'),
('113.15.c.18.A',3,'Millie Hughes-Fulford was a Texas scientist who...','["painted murals", "flew in space as an astronaut", "ran for governor", "led an army"]'::jsonb,1,'She was a payload specialist on a shuttle flight.','original'),
('113.15.c.18.B',3,'How has aerospace in Texas helped society?','["it stopped trade", "it closed schools", "space research led to new technology", "it ended farming"]'::jsonb,2,'NASA in Houston advanced science.','original'),
('113.15.c.19.A',3,'A diary written by a settler in 1850 is a...','["secondary source", "chart", "map legend", "primary source"]'::jsonb,3,'It is a firsthand record.','original'),
('113.15.c.19.A',3,'A textbook written today about the Alamo is a...','["secondary source", "primary source", "diary", "letter from the battle"]'::jsonb,0,'It was written long after the event.','original'),
('113.15.c.19.B',3,'Why compare a primary source and a secondary source on the same event?','["to avoid facts", "to see how details and views match or differ", "to guess", "to skip learning"]'::jsonb,1,'Comparing reveals different details.','original'),
('113.15.c.19.C',3,'Putting events in the order they happened is called...','["ignoring", "guessing", "sequencing", "coloring"]'::jsonb,2,'It shows chronology.','original'),
('113.15.c.19.D',3,'Which tool shows events in the order they happened over time?','["a legend", "a recipe", "a scale", "a timeline"]'::jsonb,3,'Timelines show chronology.','original'),
('113.15.c.19.E',3,'Two people read about the same event but disagree about it. This shows different...','["points of view", "titles", "weather", "maps"]'::jsonb,0,'People see events differently.','original'),
('113.15.c.19.F',3,'The central claim of a source is its...','["font", "main argument or point", "author''s age", "page number"]'::jsonb,1,'It is the key point.','original'),
('113.15.c.19.G',3,'When you make a claim in a report, you should add...','["random facts", "jokes", "supporting evidence", "rumors"]'::jsonb,2,'Evidence supports the claim.','original'),
('113.15.c.20.A',3,'A map symbol key is called a...','["compass", "border", "scale", "legend"]'::jsonb,3,'It explains the symbols.','original'),
('113.15.c.20.A',3,'The tool on a map that shows directions is the...','["compass rose", "scale", "title", "legend"]'::jsonb,0,'It shows north, south, east and west.','original'),
('113.15.c.20.B',3,'A map that shows where most Texans live is showing...','["rainfall only", "population distribution", "tall buildings", "weather today"]'::jsonb,1,'It shows where people live.','original'),
('113.15.c.21.A',3,'Using the correct word for "a person who brings settlers" means saying...','["pilot", "mayor", "empresario", "farmer"]'::jsonb,2,'Use exact social studies terms.','original'),
('113.15.c.21.B',3,'In a report, supporting ideas should...','["change the topic", "be left out", "be random", "back up the main idea"]'::jsonb,3,'Details support the main point.','original'),
('113.15.c.21.E',3,'Civil discourse means...','["talking about ideas respectfully", "insulting others", "yelling", "ignoring views"]'::jsonb,0,'It is respectful discussion.','original'),
('113.15.c.22.A',3,'A class votes on a school rule. This is a simulation of...','["a monarchy", "democratic decision making", "a dictator''s rule", "a war"]'::jsonb,1,'Voting simulates democracy.','original'),
('113.15.c.22.B',3,'When solving a problem, what comes right after identifying it?','["blame someone", "give up", "gather information", "hide it"]'::jsonb,2,'Research comes next.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
